using System;
using System.Drawing;
using System.IO;

namespace PvZLauncher
{
    public static class PvZResources
    {
        private static readonly string B64_DialogTopLeft = "";
        public static Bitmap GetDialogTopLeft() { return LoadBitmap(B64_DialogTopLeft); }

        private static readonly string B64_DialogTopMiddle = "";
        public static Bitmap GetDialogTopMiddle() { return LoadBitmap(B64_DialogTopMiddle); }

        private static readonly string B64_DialogTopRight = "";
        public static Bitmap GetDialogTopRight() { return LoadBitmap(B64_DialogTopRight); }

        private static readonly string B64_DialogCenterLeft = "";
        public static Bitmap GetDialogCenterLeft() { return LoadBitmap(B64_DialogCenterLeft); }

        private static readonly string B64_DialogCenterMiddle = "";
        public static Bitmap GetDialogCenterMiddle() { return LoadBitmap(B64_DialogCenterMiddle); }

        private static readonly string B64_DialogCenterRight = "";
        public static Bitmap GetDialogCenterRight() { return LoadBitmap(B64_DialogCenterRight); }

        private static readonly string B64_DialogBottomLeft = "";
        public static Bitmap GetDialogBottomLeft() { return LoadBitmap(B64_DialogBottomLeft); }

        private static readonly string B64_DialogBottomMiddle = "";
        public static Bitmap GetDialogBottomMiddle() { return LoadBitmap(B64_DialogBottomMiddle); }

        private static readonly string B64_DialogBottomRight = "";
        public static Bitmap GetDialogBottomRight() { return LoadBitmap(B64_DialogBottomRight); }

        private static readonly string B64_DialogHeader = "";
        public static Bitmap GetDialogHeader() { return LoadBitmap(B64_DialogHeader); }

        private static readonly string B64_ButtonLeft = "";
        public static Bitmap GetButtonLeft() { return LoadBitmap(B64_ButtonLeft); }

        private static readonly string B64_ButtonMiddle = "";
        public static Bitmap GetButtonMiddle() { return LoadBitmap(B64_ButtonMiddle); }

        private static readonly string B64_ButtonRight = "";
        public static Bitmap GetButtonRight() { return LoadBitmap(B64_ButtonRight); }

        private static readonly string B64_ButtonDownLeft = "";
        public static Bitmap GetButtonDownLeft() { return LoadBitmap(B64_ButtonDownLeft); }

        private static readonly string B64_ButtonDownMiddle = "";
        public static Bitmap GetButtonDownMiddle() { return LoadBitmap(B64_ButtonDownMiddle); }

        private static readonly string B64_ButtonDownRight = "";
        public static Bitmap GetButtonDownRight() { return LoadBitmap(B64_ButtonDownRight); }

        private static Bitmap LoadBitmap(string b64)
        {
            if (string.IsNullOrEmpty(b64)) return new Bitmap(1, 1);
            byte[] bytes = Convert.FromBase64String(b64);
            using (MemoryStream ms = new MemoryStream(bytes))
            {
                return new Bitmap(ms);
            }
        }
    }
}